const { useRef } = React;

function Search() {
  const inputRef = useRef(null);

  function focusInput() {
    inputRef.current.focus();
  }

  return (
    <section>
      <input ref={inputRef} aria-label="검색어" />
      <button type="button" onClick={focusInput}>입력창 선택</button>
    </section>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<Search />);

